#!/usr/bin/env python3
"""A derived fallback link input must never replace the report's target."""
import copy
import json
import os
from pathlib import Path
import re
import sys
import tempfile
import unittest

ROOT = Path(__file__).resolve().parents[2]
sys.path.insert(0, str(ROOT))
from tools.project import Object, ProjectConfig, generate_build_ninja, generate_objdiff_config


class FallbackLinkOverrideTests(unittest.TestCase):
    def setUp(self):
        self.directory = tempfile.TemporaryDirectory()
        self.previous_directory = Path.cwd()
        os.chdir(self.directory.name)
        self.addCleanup(self.directory.cleanup)
        self.addCleanup(os.chdir, self.previous_directory)
        self.config = ProjectConfig()
        self.config.version = 'GC6E01'
        self.config.config_path = Path('config.yml')
        self.config.check_sha_path = Path('build.sha1')
        self.config.linker_version = 'GC/1.2.5n'
        self.config.ldflags = []
        self.config.libs = []
        self.config.asm_dir = None
        self.config.dtk_tag = 'v1.8.3'
        self.config.objdiff_tag = 'v3.6.1'
        self.config.compilers_tag = 'test'
        self.config.binutils_tag = 'test'
        self.config.sjiswrap_tag = 'v1.2.2'
        self.config.wibo_tag = '1.0.3'
        self.config.custom_build_rules = [{
            'name': 'test_link_copy',
            'command': '$python tools/link_vector_object.py $in $out',
        }]
        self.original = 'originals/vector.o'
        self.output = Path('build/GC6E01/link/crt/interrupt_vectors.o')
        self.key = ('main', 'crt/interrupt_vectors')
        self.override = {
            'rule': 'test_link_copy',
            'output': self.output,
            'implicit': [Path('tools/link_vector_object.py')],
        }
        self.config.fallback_link_overrides = {self.key: self.override}
        self.build_config = {
            'version': '1.8.3', 'name': 'main', 'module_id': 0,
            'ldscript': 'build/GC6E01/ldscript.lcf', 'entry': '_start',
            'units': [
                {'name': 'crt/interrupt_vectors', 'object': self.original, 'autogenerated': False},
                {'name': 'crt/other', 'object': 'originals/other.o', 'autogenerated': False},
            ],
            'modules': [], 'links': [],
        }

    def generated_ninja(self, objects=None):
        generate_build_ninja(self.config, objects or {}, self.build_config)
        return re.sub(r'\$\n\s*', '', Path('build.ninja').read_text())

    def test_link_copy_is_scoped_and_report_target_and_credit_are_unchanged(self):
        before = copy.deepcopy(self.build_config)
        self.config.fallback_link_overrides = {}
        generate_objdiff_config(self.config, {}, self.build_config)
        report_before = json.loads(Path('objdiff.json').read_text())
        self.config.fallback_link_overrides = {self.key: self.override}
        ninja = self.generated_ninja()
        self.assertIn(
            f'build {self.output}: test_link_copy {self.original} | tools/link_vector_object.py', ninja)
        link = next(line for line in ninja.splitlines() if line.startswith('build build/GC6E01/main.elf:'))
        self.assertIn(str(self.output), link)
        self.assertIn('originals/other.o', link)
        self.assertNotIn(self.original, link)
        for prefix in ('build all_source:', 'build build/GC6E01/report.json:'):
            edge = next(line for line in ninja.splitlines() if line.startswith(prefix))
            self.assertNotIn(str(self.output), edge)
        generate_objdiff_config(self.config, {}, self.build_config)
        report_after = json.loads(Path('objdiff.json').read_text())
        self.assertEqual(self.build_config, before)
        self.assertEqual(report_after, report_before)
        unit = next(u for u in report_after['units'] if u['name'] == 'main/crt/interrupt_vectors')
        self.assertEqual(unit['target_path'], self.original)
        self.assertFalse(unit.get('base_path'))
        self.assertFalse(unit['metadata'].get('source_path'))
        self.assertFalse(unit['metadata'].get('complete'))

    def test_configured_incomplete_object_uses_same_fallback_selection(self):
        obj = Object(False, 'crt/interrupt_vectors', source='crt/interrupt_vectors.c', cflags=[])
        obj = obj.resolve(self.config, {})
        ninja = self.generated_ninja({obj.name: obj})
        self.assertIn(f'build {self.output}: test_link_copy {self.original}', ninja)

    def test_source_built_object_cannot_be_replaced_by_fallback_override(self):
        source = Path('src/crt/interrupt_vectors.c')
        source.parent.mkdir(parents=True)
        source.write_text('void example(void) {}\n')
        obj = Object(True, 'crt/interrupt_vectors', source='crt/interrupt_vectors.c', cflags=[])
        obj = obj.resolve(self.config, {})
        with self.assertRaisesRegex(SystemExit, 'not used by an original fallback'):
            self.generated_ninja({obj.name: obj})

    def test_unknown_unit_or_module_is_rejected(self):
        for key in [('other_module', self.key[1]), (self.key[0], 'unknown/unit')]:
            with self.subTest(key=key):
                self.config.fallback_link_overrides = {key: self.override}
                with self.assertRaisesRegex(SystemExit, 'not used by an original fallback'):
                    self.generated_ninja()

    def test_overwriting_original_or_undeclared_rule_is_rejected(self):
        self.override['output'] = Path(self.original)
        with self.assertRaisesRegex(SystemExit, 'preserve its original target'):
            self.generated_ninja()
        self.override['output'] = self.output
        self.override['rule'] = 'undeclared_rule'
        with self.assertRaisesRegex(SystemExit, 'declared custom rule'):
            self.generated_ninja()


if __name__ == '__main__':
    unittest.main()
